import{Mt as e,ft as t,n,ut as r}from"./chunks/framework.DMrgfsfe.js";var i=JSON.parse(`{"title":"React Pro Components Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md","lastUpdated":1793256826000}`),a={name:`en/guide/compatibility.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t('<h1 id="react-pro-components-compatibility" tabindex="-1">React Pro Components Compatibility <a class="header-anchor" href="#react-pro-components-compatibility" aria-label="Permalink to “React Pro Components Compatibility”">​</a></h1><p>This alignment references <code>@ant-design/pro-components@3.1.15-7</code>, pinned to <code>3bf43278d39f2d31489749132982488f57a9eb5e</code>. Vue mappings preserve parameter semantics and behavior. See <a href="./pro-components-v3">v3 migration</a> for scope and changed defaults.</p><p>Status: <span class="compat-ok">supported</span>, <span class="compat-map">Vue mapping</span>, <span class="compat-partial">initial boundary</span>.</p><h2 id="core-mapping" tabindex="-1">Core mapping <a class="header-anchor" href="#core-mapping" aria-label="Permalink to “Core mapping”">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">supported</span></td><td>Shared by all three components</td></tr><tr><td><code>request(params, sort, filter)</code></td><td>Same Promise contract</td><td><span class="compat-ok">supported</span></td><td>Returns <code>{ data, total?, success? }</code></td></tr><tr><td><code>actionRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td><td>Similar instance method names</td></tr><tr><td><code>formRef</code></td><td>Vue Ref / callback</td><td><span class="compat-map">Vue mapping</span></td><td>Reads the form instance; see each component API</td></tr><tr><td><code>editableFormRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td><td>Editing data and action methods are exposed on the component</td></tr><tr><td><code>value</code> / <code>onChange</code></td><td><code>v-model</code></td><td><span class="compat-map">Vue mapping</span></td><td>Standard <code>update:*</code> events</td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue mapping</span></td><td>Shared single/multiple edit state</td></tr><tr><td>ReactNode props</td><td>Named slots / render callbacks</td><td><span class="compat-map">Vue mapping</span></td><td>Templates first, callbacks when reusable</td></tr><tr><td><code>onRequestError</code></td><td><code>request-error</code></td><td><span class="compat-map">Vue mapping</span></td><td>Existing rows are preserved</td></tr></tbody></table><h2 id="search-collapse" tabindex="-1">Search collapse <a class="header-anchor" href="#search-collapse" aria-label="Permalink to “Search collapse”">​</a></h2><p><code>ProTable.search</code> keeps the core React semantics:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behavior</th></tr></thead><tbody><tr><td><code>defaultCollapsed</code></td><td>Initializes uncontrolled collapse state only</td></tr><tr><td><code>collapsed</code></td><td>Controlled state; the parent updates it</td></tr><tr><td><code>span</code></td><td>Number or partial breakpoint map; defaults to 1 / 2 / 3 items per row by container width</td></tr><tr><td><code>labelWidth</code></td><td>Numbers are pixels; <code>auto</code> keeps intrinsic sizing</td></tr><tr><td><code>searchText</code> / <code>resetText</code></td><td>Search and reset labels</td></tr><tr><td><code>onCollapse(next)</code></td><td>Collapse-state callback</td></tr></tbody></table><p>Vue also emits <code>search-collapse</code>:</p><div class="language-vue" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ProTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ collapsed, span: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">search-collapse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">collapsed </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $event</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>Collapsed mode renders the first row only. The expand/collapse control appears only when more fields exist.</p><h2 id="named-slots" tabindex="-1">Named slots <a class="header-anchor" href="#named-slots" aria-label="Permalink to “Named slots”">​</a></h2><p>Column slot names use <code>column.key</code> first and <code>dataIndex</code> otherwise. Array paths are dot-joined, so <code>[&#39;profile&#39;, &#39;name&#39;]</code> becomes <code>profile.name</code>.</p><table tabindex="0"><thead><tr><th>Component</th><th>Slot</th><th>Slot props</th></tr></thead><tbody><tr><td>ProTable</td><td><code>toolbar-title</code>, <code>toolbar-actions</code></td><td>Toolbar content</td></tr><tr><td>ProTable</td><td><code>header-${columnKey}</code></td><td><code>{ column }</code></td></tr><tr><td>ProTable</td><td><code>cell-${columnKey}</code> or <code>${columnKey}</code></td><td><code>{ value, record, index, column, editable }</code></td></tr><tr><td>SchemaForm</td><td><code>field-${path}</code>, <code>${path}</code>, or the column <code>key</code></td><td><code>{ value, record, column, dependencies, update }</code></td></tr><tr><td>SchemaForm</td><td><code>label-${path}</code></td><td><code>{ column, record }</code></td></tr><tr><td>SchemaForm</td><td><code>submitter</code></td><td><code>{ values, current }</code></td></tr></tbody></table><p>Other slots not consumed by ProTable are forwarded to the underlying Antdv Next Table.</p><h2 id="valuetype-support" tabindex="-1"><code>valueType</code> support <a class="header-anchor" href="#valuetype-support" aria-label="Permalink to “valueType support”">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Types</th><th>ProTable / EditableProTable</th><th>SchemaForm</th></tr></thead><tbody><tr><td>Text</td><td><code>text</code>, <code>textarea</code>, <code>password</code></td><td>Input, Textarea, Password search/edit controls and formatted display</td><td>Input, Textarea, Password</td></tr><tr><td>Numeric</td><td><code>digit</code>, <code>money</code>, <code>percent</code>, <code>slider</code></td><td>Numeric search and inline InputNumber / Slider</td><td>InputNumber, Slider, and money/percent affordances</td></tr><tr><td>Choices</td><td><code>select</code>, <code>treeSelect</code>, <code>radio</code>, <code>segmented</code></td><td>Choice search/edit controls with <code>valueEnum</code></td><td>Select, TreeSelect, Radio, and Segmented</td></tr><tr><td>State</td><td><code>checkbox</code>, <code>switch</code></td><td>Inline Checkbox / Switch</td><td>Checkbox(Group) / Switch</td></tr><tr><td>Date/time</td><td><code>date</code>, <code>dateTime</code>, <code>dateRange</code>, <code>dateTimeRange</code>, <code>time</code>, <code>timeRange</code></td><td>Matching date/time controls and formatted display</td><td>Matching date/time controls</td></tr><tr><td>Table</td><td><code>index</code>, <code>indexBorder</code>, <code>option</code></td><td>Index and action columns</td><td>No field generated</td></tr><tr><td>Composition</td><td><code>group</code>, <code>formList</code>, <code>formSet</code>, <code>divider</code>, <code>dependency</code></td><td>No data column generated</td><td>Groups, dynamic lists, sets, dividers, and dependencies</td></tr></tbody></table><h2 id="protable-capabilities" tabindex="-1">ProTable capabilities <a class="header-anchor" href="#protable-capabilities" aria-label="Permalink to “ProTable capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Local/remote data, search, pagination, sort, filters</td><td><span class="compat-ok">supported</span></td><td>Last request wins</td></tr><tr><td>Column visibility, order, fixed state, persistence</td><td><span class="compat-ok">supported</span></td><td>The built-in panel controls visibility, order, and fixed position; <code>columnsState</code> supports controlled state and persistence</td></tr><tr><td>Reload, density, fullscreen, row selection</td><td><span class="compat-ok">supported</span></td><td>Options, events, and instance API</td></tr><tr><td>Polling, focus revalidation, manual initial request</td><td><span class="compat-ok">supported</span></td><td><code>polling</code> / <code>revalidateOnFocus</code> / <code>manualRequest</code></td></tr><tr><td>Single, multiple, creator, and tree editing</td><td><span class="compat-ok">supported</span></td><td>Shared with EditableProTable</td></tr><tr><td>React-only DOM and portal props</td><td><span class="compat-partial">not ported</span></td><td>Use Vue slots and Antdv Next props</td></tr></tbody></table><h2 id="editableprotable-mapping" tabindex="-1">EditableProTable mapping <a class="header-anchor" href="#editableprotable-mapping" aria-label="Permalink to “EditableProTable mapping”">​</a></h2><table tabindex="0"><thead><tr><th>React API</th><th>Vue API</th><th>Status</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>v-model:value</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>controlled</code></td><td>Standard <code>v-model</code> semantics</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>editableKeys</code></td><td><code>v-model:editable-keys</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>recordCreatorProps</code></td><td><code>record</code>, <code>position</code>, <code>parentKey</code>, <code>newRecordType</code>, <code>creatorButtonText</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>maxLength</code></td><td><code>maxLength</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>onValuesChange</code></td><td>Same prop or <code>values-change</code> event</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>onTableChange</code></td><td>Same prop or <code>table-change</code> event</td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>editableFormRef</code></td><td>Component <code>ref</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>editable.form</code></td><td><code>editable.formRef</code> reads the actual native Form instance</td><td><span class="compat-map">Vue mapping</span></td></tr></tbody></table><p><code>value</code> is the only controlled whole-table data entry point; a conflicting <code>dataSource</code> prop is intentionally not exposed.</p><p>This convention applies to <code>EditableProTable</code>. <code>RowEditorTable</code> and <code>CellEditorTable</code> support both <code>v-model:value</code> and <code>v-model:dataSource</code>. When both are supplied, <code>value</code> takes precedence; choose one model consistently in an application.</p><p><code>editable.formRef</code> is a <code>Ref&lt;FormInstance | undefined&gt;</code> bound to the current editing form on mount, ref replacement, and unmount. Native Vue Form cannot inject an existing React Form instance. The legacy <code>editable.form</code> type remains deprecated; migrate to reading <code>editable.formRef</code> and configure form props through <code>editable.formProps</code>.</p><h2 id="schemaform-mapping" tabindex="-1">SchemaForm mapping <a class="header-anchor" href="#schemaform-mapping" aria-label="Permalink to “SchemaForm mapping”">​</a></h2><table tabindex="0"><thead><tr><th>React SchemaForm</th><th>Vue SchemaForm</th><th>Status</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>columns</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>layoutType</code></td><td><code>layoutType</code></td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>Form</code> / <code>Embed</code></td><td>Same layouts</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>ModalForm</code> / <code>DrawerForm</code></td><td>Same layouts + <code>v-model:open</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>QueryFilter</code> / <code>LightFilter</code></td><td>Same layouts</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>StepForm</code> / <code>StepsForm</code></td><td>Same layouts + <code>v-model:current</code></td><td><span class="compat-map">Vue mapping</span></td></tr><tr><td><code>group</code> / <code>formList</code> / <code>formSet</code></td><td>Same <code>valueType</code> values</td><td><span class="compat-ok">supported</span></td></tr><tr><td><code>dependency</code></td><td><code>dependencies</code> plus a dependency column</td><td><span class="compat-ok">supported</span></td></tr></tbody></table><p><code>urlSync</code> is a Vue-side extension. <code>true</code> writes fields into query parameters, <code>{ key: &#39;filters&#39; }</code> stores the complete model as JSON in one parameter, and <code>{ mode: &#39;hash&#39; }</code> targets the hash. Browser history navigation hydrates the form again.</p><p>Regular fields share the ProFormFields core with ProTable search/edit controls. The formal column editor is <code>formItemRender</code>; legacy <code>renderFormItem</code> remains an alias. Table column <code>render</code> receives <code>(dom, record, index, action, schema)</code>.</p><h2 id="proformfields-mapping" tabindex="-1">ProFormFields mapping <a class="header-anchor" href="#proformfields-mapping" aria-label="Permalink to “ProFormFields mapping”">​</a></h2><p>Standalone fields use template-friendly names such as <code>ProFormText</code>, <code>ProFormSelect</code>, <code>ProFormTreeSelect</code>, and <code>ProFormUploadButton</code>, with additional Cascader, ColorPicker, Rate, DigitRange, time, and date variants. The default <code>fieldMode=&quot;form-item&quot;</code> creates a FormItem; <code>fieldMode=&quot;field&quot;</code> renders only the bare control.</p><table tabindex="0"><thead><tr><th>React compound name</th><th>Recommended Vue template name</th><th>Relationship</th></tr></thead><tbody><tr><td><code>ProFormText.Password</code></td><td><code>ProFormTextPassword</code></td><td>Both reference the same component</td></tr><tr><td><code>ProFormRadio.Group</code></td><td><code>ProFormRadioGroup</code></td><td>Both reference the same component</td></tr></tbody></table><p>Every field exposes standard <code>v-model</code>. The shared core bridges single Checkbox/Switch <code>checked</code>, Upload <code>fileList</code>, and other controls&#39; <code>value</code> contracts to <code>modelValue</code>. Select, TreeSelect, Checkbox Group, RadioGroup, and Segmented share the <code>options</code> / <code>valueEnum</code> / <code>request</code> protocol.</p><p>Captcha reads and validates <code>phoneName</code> before passing it to <code>onGetCaptcha</code>; applications supply the sending operation. UploadButton and UploadDragger use the supplied <code>action</code> / <code>customRequest</code> upload contract.</p><h2 id="configuration-and-composed-forms" tabindex="-1">Configuration and composed forms <a class="header-anchor" href="#configuration-and-composed-forms" aria-label="Permalink to “Configuration and composed forms”">​</a></h2><p>Native ConfigProvider locale, direction, prefixes, theme algorithms, global tokens, and native component tokens are inherited. ProConfigProvider / ProProvider provide Pro <code>token</code>, <code>intl</code>, and <code>valueTypeMap</code>. Use <code>ProConfigProvider.token</code> for Pro extensions. Prefer <code>classes/styles</code>; legacy <code>classNames</code> remains an alias. Public classes use <code>ant-pro-*</code>.</p><p>ProForm composes child fields; BetaSchemaForm/SchemaForm consume schemas. Group, FieldSet, List, Dependency, and Item share form context. ModalForm and DrawerForm await <code>onFinish</code> and close only on <code>true</code>. Column callbacks use <code>render(dom, record, index, action, schema)</code>.</p><h2 id="component-refs" tabindex="-1">Component refs <a class="header-anchor" href="#component-refs" aria-label="Permalink to “Component refs”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Methods</th></tr></thead><tbody><tr><td>ProTable</td><td><code>reload</code>, <code>reset</code>, <code>setPageInfo</code>, <code>clearSelected</code>, <code>fullScreen</code>, <code>scrollTo</code>, <code>startEditable</code>, <code>saveEditable</code>, <code>cancelEditable</code>, <code>addEditRecord</code></td></tr><tr><td>EditableProTable</td><td>ProTable methods + <code>getRowData</code>, <code>getRowsData</code>, <code>setRowData</code></td></tr><tr><td>SchemaForm</td><td><code>validate</code>, <code>reset</code>, <code>getFieldsValue</code>, <code>setFieldsValue</code>, <code>submit</code>, <code>open</code>, <code>close</code>, <code>next</code>, <code>prev</code></td></tr></tbody></table><h2 id="project-release-convention" tabindex="-1">Project release convention <a class="header-anchor" href="#project-release-convention" aria-label="Permalink to “Project release convention”">​</a></h2><p>Changesets and GitHub Actions are project conventions, not React APIs. Describe npm-facing changes with <code>pnpm changeset</code>. Successful CI on <code>main</code> maintains the version PR; npm publishing only runs when <code>NPM_TOKEN</code> exists, with provenance enabled.</p><h2 id="explicitly-out-of-scope" tabindex="-1">Explicitly out of scope <a class="header-anchor" href="#explicitly-out-of-scope" aria-label="Permalink to “Explicitly out of scope”">​</a></h2><p><a href="./../components/pro-card">ProCard</a> covers theme containers, title/actions, loading, collapse, semantic styles, tabs, responsive columns, Group, and Divider. ProList/BaseProList, ProDescriptions, and table helpers extend display workflows.</p><p>Grid items in <code>ProList</code> reuse the existing <code>ProCard</code> and accept <code>itemCardProps</code>. <code>metas.actions.cardActionProps</code> places actions in the top-right <code>extra</code> area by default, or in the footer with <code>actions</code>; this does not introduce CheckCard.</p><p>This alignment excludes ProSkeleton, LoginForm/LoginFormPage, PageContainer/ProLayout, StatisticCard/CheckCard and their new component families. The network boundary is the Promise <code>request</code> callback.</p>',44)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};